export const PATHWAYS = {"dubai.eid":{"id":"dubai.eid","title":{"en":"Who is arranging your UAE residency?","ar":"من يتولى إجراءات إقامتك في الإمارات؟"},"sub":{"en":"Your answer changes what you need to do. Most newcomers don’t do this alone.","ar":"إجابتك تغيّر ما عليك فعله. معظم القادمين الجدد لا يقومون بذلك وحدهم."},"options":[{"name":{"en":"My university","ar":"جامعتي"},"journey":"dubai.eid.student"},{"name":{"en":"My employer","ar":"جهة عملي"},"journey":"dubai.eid.employee"},{"name":{"en":"A family member","ar":"أحد أفراد عائلتي"},"journey":"dubai.eid.family"},{"name":{"en":"I’m arranging it myself","ar":"أتولى ذلك بنفسي"},"journey":"dubai.eid.self"}],"dontKnow":{"title":{"en":"That’s OK. Here’s how to tell.","ar":"لا بأس. إليك كيف تعرف."},"items":[{"en":"You came to study: your university usually sponsors your visa. Its visa office runs the process.","ar":"جئت للدراسة: عادةً تكفل جامعتك تأشيرتك، ويتولى مكتب التأشيرات فيها الإجراءات."},{"en":"You came to work: your employer usually handles it. The person who does this is often called the PRO (Public Relations Officer). Ask HR who your PRO is.","ar":"جئت للعمل: عادةً تتولى جهة عملك ذلك، والشخص المسؤول يُسمّى غالباً «مندوب العلاقات العامة» (PRO). اسأل الموارد البشرية عنه."},{"en":"You came to join family: the family member sponsoring you usually applies.","ar":"جئت للانضمام إلى عائلتك: عادةً يقدّم الطلب فرد العائلة الذي يكفلك."}],"tip":{"en":"Don’t start an application yourself until you’ve checked. Someone may already be doing it for you.","ar":"لا تبدأ طلباً بنفسك قبل أن تتأكد، فقد يكون أحدهم يقوم بذلك عنك."}}},"dubai.ins":{"id":"dubai.ins","title":{"en":"Who arranges your health insurance?","ar":"من يرتّب تأمينك الصحي؟"},"sub":{"en":"In Dubai it depends on who sponsors your visa. Pick the closest one.","ar":"في دبي يعتمد ذلك على كفيل تأشيرتك. اختر الأقرب."},"options":[{"name":{"en":"I’m a student (my university sponsors my visa)","ar":"أنا طالب (جامعتي تكفل تأشيرتي)"},"journey":"dubai.ins.student"},{"name":{"en":"I work here (my employer sponsors my visa)","ar":"أعمل هنا (جهة عملي تكفل تأشيرتي)"},"journey":"dubai.ins.employee"},{"name":{"en":"A family member sponsors my visa","ar":"أحد أفراد عائلتي يكفل تأشيرتي"},"journey":"dubai.ins.family"},{"name":{"en":"I sponsor myself","ar":"أكفل نفسي"},"journey":"dubai.ins.self"},{"name":{"en":"I’m visiting","ar":"أنا زائر"},"journey":"dubai.ins.visitor"}],"dontKnow":{"title":{"en":"That’s OK. Here’s how to tell.","ar":"لا بأس. إليك كيف تعرف."},"items":[{"en":"Your visa sponsor is whoever applied for your residence visa: usually your university, your employer, or a family member.","ar":"كفيل تأشيرتك هو من تقدّم بطلب تأشيرة إقامتك: عادةً جامعتك أو جهة عملك أو أحد أفراد عائلتك."},{"en":"In Dubai, that sponsor is responsible for your health insurance.","ar":"وفي دبي، يكون هذا الكفيل مسؤولاً عن تأمينك الصحي."},{"en":"On a visit visa, you’re a visitor.","ar":"إذا كانت لديك تأشيرة زيارة، فأنت زائر."}],"tip":{"en":"Don’t buy a residence plan yourself until you know. Your sponsor may already have one for you.","ar":"لا تشترِ خطة إقامة بنفسك قبل أن تتأكد، فقد يكون كفيلك قد رتّب واحدة لك."}}}};
export const CONTACTS = {"visa":{"who":{"en":"Your university’s visa office","ar":"مكتب التأشيرات في جامعتك"},"whoIn":{"en":"your university’s visa office","ar":"مكتب التأشيرات في جامعتك"},"why":{"en":"They sponsor your visa and run this part of your application. Only they can see it or change it.","ar":"فهو كفيل تأشيرتك ويتولى هذا الجزء من طلبك، ولا أحد غيره يستطيع الاطلاع عليه أو تعديله."},"ready":[{"en":"Your full name, as in your passport","ar":"اسمك الكامل كما في جواز السفر"},{"en":"Your passport number","ar":"رقم جواز سفرك"},{"en":"Your student ID number","ar":"رقمك الجامعي"},{"en":"Your application number (PRAN), if you have it","ar":"رقم الطلب (PRAN) إن كان لديك"},{"en":"Any email or letter about this","ar":"أي رسالة أو خطاب يخص هذا الأمر"}],"how":{"en":"Their email address is usually in your offer or welcome email. Can’t find it? Search your university’s website for “student visa”, or ask at the student services desk on campus.","ar":"يوجد بريدهم الإلكتروني عادةً في رسالة القبول أو الترحيب. لا تجده؟ ابحث في موقع جامعتك عن «تأشيرة الطالب»، أو اسأل في مكتب خدمات الطلاب في الحرم الجامعي."},"replyDays":3},"icp":{"who":{"en":"ICP (the Federal Authority for Identity and Citizenship)","ar":"الهيئة الاتحادية للهوية والجنسية"},"why":{"en":"They issue Emirates IDs and can check where your ID application is.","ar":"هي الجهة التي تُصدر الهوية الإماراتية ويمكنها التحقق من حالة طلبك."},"ready":[{"en":"Your application number (PRAN)","ar":"رقم الطلب (PRAN)"},{"en":"Your passport number","ar":"رقم جواز سفرك"}],"how":{"en":"Call 600 522222. From outside the UAE: +971 600 522222.","ar":"اتصل على 600 522222. من خارج الإمارات: ‎+971 600 522222."},"phone":"600 522222","replyDays":0}};
